448	// TestConfirmRecoveryCurrentMayBeCorruptOrDeleted 即使槽当前指向的记录已损坏
449	// 或被删除，只要调用方给出的当前标识与之一致，就不能妨碍从本槽完好旧记录
450	// 恢复。
451	func TestConfirmRecoveryCurrentMayBeCorruptOrDeleted(t *testing.T) {
452		a, dir := newTestArchive(t)
453		ids := saveN(t, a, "s", 2) // r2 r1 r0
454	
455		// 情形一：当前记录损坏。
456		corruptChecksum(t, dir, ids[0])
457		pv, err := a.PreviewRecovery("s", []string{"v1"})
458		if err != nil {
459			t.Fatal(err)
460		}
461		if pv.Current != ids[0] || pv.Source != ids[1] {
462			t.Fatalf("预览错误: %+v", pv)
463		}
464		info, err := a.ConfirmRecovery("s", pv.Current, pv.Source, []string{"v1"})
465		if err != nil {
466			t.Fatalf("当前损坏不应妨碍恢复: %v", err)
467		}
468		if info.Parent != ids[1] {
469			t.Fatalf("父应为完好旧记录 %s，得到 %s", ids[1], info.Parent)
470		}
471	
472		// 情形二：另起一槽，当前记录被删除。
473		del := saveN(t, a, "d", 2)
474		deleteRecord(t, dir, del[0])
475		pv2, err := a.PreviewRecovery("d", []string{"v1"})
476		if err != nil {
477			t.Fatal(err)
478		}
479		if pv2.Current != del[0] || pv2.Source != del[1] {
480			t.Fatalf("预览错误: %+v", pv2)
481		}
482		info2, err := a.ConfirmRecovery("d", pv2.Current, pv2.Source, []string{"v1"})
483		if err != nil {
484			t.Fatalf("当前被删除不应妨碍恢复: %v", err)
485		}
486		if rec, err := a.Latest("d", []string{"v1"}); err != nil || rec.ID != info2.ID {
487			t.Fatalf("恢复后槽指向错误: %+v err=%v", rec, err)
488		}
489	}
490	
491	// TestConfirmRecoverySourceValidation 来源的归属、内容与版本在确认时重新
492	// 判断，且不改选其他来源，也不使用调用方修改过的预览状态。
493	func TestConfirmRecoverySourceValidation(t *testing.T) {
494		a, dir := newTestArchive(t)
495		ids := saveN(t, a, "s", 3)
496	
497		// 其他槽的记录：按记录不存在拒绝。
498		other := saveBase(t, a, "o")
499		if _, err := a.ConfirmRecovery("s", ids[0], other.ID, []string{"v1"}); !errors.As(err, new(*NotFoundError)) {
500			t.Fatalf("他槽记录应 NotFound，得到 %T: %v", err, err)
501		}
502	
503		// 未生效的孤儿记录：文件完好但不在本槽历史中，按不存在拒绝。
504		w := baseWorld(t)
505		if _, err := w.Apply(Commit{Time: 8}); err != nil {
506			t.Fatal(err)
507		}
508		orphan := writeRawRecord(t, a, ids[0], false, w.Snapshot())
509		if _, err := a.ConfirmRecovery("s", ids[0], orphan, []string{"v1"}); !errors.As(err, new(*NotFoundError)) {
510			t.Fatalf("孤儿记录应 NotFound，得到 %T: %v", err, err)
511		}
512	
513		// 来源后来被删除：不存在，且不自动改选别的来源。
514		deleteRecord(t, dir, ids[2])
515		if _, err := a.ConfirmRecovery("s", ids[0], ids[2], []string{"v1"}); !errors.As(err, new(*NotFoundError)) {
516			t.Fatalf("来源被删应 NotFound，得到 %T: %v", err, err)
517		}
518	
519		// 来源后来损坏：损坏。
520		corruptChecksum(t, dir, ids[1])
521		if _, err := a.ConfirmRecovery("s", ids[0], ids[1], []string{"v1"}); !errors.As(err, new(*CorruptError)) {
522			t.Fatalf("来源损坏应 Corrupt，得到 %T: %v", err, err)
523		}
524	
525		// 来源版本不被确认方接受：版本拒绝。
526		if _, err := a.ConfirmRecovery("s", ids[0], ids[3], []string{"v9"}); !errors.As(err, new(*VersionRejectedError)) {
527			t.Fatalf("来源版本不被接受应 VersionRejected，得到 %T: %v", err, err)
528		}
529	
530		// 来源失效时槽指向与历史保持不变。
531		latest, err := a.readLatestLocked("s")
532		if err != nil {
533			t.Fatal(err)
534		}
535		if latest != ids[0] {
536			t.Fatalf("失败确认不应移动槽指针: %s != %s", latest, ids[0])
537		}
538	}
539	
540	// TestConfirmRecoveryIgnoresTamperedPreviewState 调用方篡改预览返回的状态
541	// 不影响确认结果：新记录内容始终以磁盘上重新校验过的来源为准。
542	func TestConfirmRecoveryIgnoresTamperedPreviewState(t *testing.T) {
543		a, _ := newTestArchive(t)
544		saveN(t, a, "s", 2)
545		pv, err := a.PreviewRecovery("s", []string{"v1"})
546		if err != nil {
547			t.Fatal(err)
548		}
549		// 即便调用方把预览状态改得面目全非，确认只接收标识，无法被污染。
550		pv.State.Seed = -1
551		pv.State.Time = 999
552		info, err := a.ConfirmRecovery("s", pv.Current, pv.Source, []string{"v1"})
553		if err != nil {
554			t.Fatalf("确认失败: %v", err)
555		}
556		rec, err := a.Record("s", info.ID, []string{"v1"})
557		if err != nil {
558			t.Fatal(err)
559		}
560		if rec.State.Seed != 42 || rec.State.Time != 2 {
561			t.Fatalf("新记录应以磁盘来源为准，却被调用方状态污染: %+v", rec.State)
562		}
563	}
564	
565	// TestConfirmRecoveryConcurrent 多个实例基于同一当前标识并发确认，恰好一个
566	// 成功，其余冲突；再用同一旧当前标识确认仍冲突。
567	func TestConfirmRecoveryConcurrent(t *testing.T) {
568		a, dir := newTestArchive(t)
569		ids := saveN(t, a, "s", 2)
570		corruptChecksum(t, dir, ids[0])
571	
572		pv, err := a.PreviewRecovery("s", []string{"v1"})
573		if err != nil {
574			t.Fatal(err)
575		}
576	
577		const n = 6
578		var wg sync.WaitGroup
579		var mu sync.Mutex
580		wins, conflicts := 0, 0
581		for i := 0; i < n; i++ {
582			wg.Add(1)
583			go func() {
584				defer wg.Done()
585				ga, err := Open(dir)
586				if err != nil {
587					t.Error(err)
588					return
589				}
590				_, err = ga.ConfirmRecovery("s", pv.Current, pv.Source, []string{"v1"})
591				mu.Lock()
592				defer mu.Unlock()
593				switch {
594				case err == nil:
595					wins++
596				case errors.As(err, new(*ConflictError)):
597					conflicts++
598				default:
599					t.Errorf("非冲突错误: %v", err)
600				}
601			}()
602		}
603		wg.Wait()
604		if wins != 1 || conflicts != n-1 {
605			t.Fatalf("期望 1 成功 %d 冲突，得到 %d 成功 %d 冲突", n-1, wins, conflicts)
606		}
607	
608		// 同一当前标识再确认必然冲突。
609		if _, err := a.ConfirmRecovery("s", pv.Current, pv.Source, []string{"v1"}); !errors.As(err, new(*ConflictError)) {
610			t.Fatalf("同一当前标识上第二次确认应冲突，得到 %T: %v", err, err)
611		}
612		rec, err := a.Latest("s", []string{"v1"})
613		if err != nil {
614			t.Fatal(err)
615		}
616		if rec.Parent != pv.Source {
617			t.Fatalf("胜出恢复记录父应为 %s，得到 %s", pv.Source, rec.Parent)
618		}
619	}
620	
621	// TestConfirmRecoveryRacesWithReplace 确认与普通覆盖竞争同一当前标识：
622	// 最多一个成功。覆盖先得手时确认冲突；确认先得手时覆盖冲突。
623	func TestConfirmRecoveryRacesWithReplace(t *testing.T) {
624		a, _ := newTestArchive(t)
625		saveN(t, a, "s", 1)
626		pv, err := a.PreviewRecovery("s", []string{"v1"})
627		if err != nil {
628			t.Fatal(err)
629		}
630	
631		// 覆盖先成功：确认冲突，槽停在覆盖记录上。
632		w := baseWorld(t)
633		if _, err := w.Apply(Commit{Time: 5}); err != nil {
634			t.Fatal(err)
635		}
636		r2, err := a.Replace("s", w, pv.Current)
637		if err != nil {
638			t.Fatal(err)
639		}
640		if _, err := a.ConfirmRecovery("s", pv.Current, pv.Source, []string{"v1"}); !errors.As(err, new(*ConflictError)) {
641			t.Fatalf("覆盖抢先时确认应冲突，得到 %T: %v", err, err)
642		}
643	
644		// 确认先成功（基于 r2）：再用 r2 覆盖应冲突。
645		pv2, err := a.PreviewRecovery("s", []string{"v1"})
646		if err != nil {
647			t.Fatal(err)
648		}
649		info, err := a.ConfirmRecovery("s", pv2.Current, pv2.Source, []string{"v1"})
650		if err != nil {
651			t.Fatal(err)
652		}
653		if _, err := a.Replace("s", w, r2.ID); !errors.As(err, new(*ConflictError)) {
654			t.Fatalf("确认抢先时旧覆盖应冲突，得到 %T: %v", err, err)
655		}
656		latest, err := a.Latest("s", []string{"v1"})
657		if err != nil || latest.ID != info.ID {
658			t.Fatalf("槽应停在恢复记录上: %+v err=%v", latest, err)
659		}
660	}
661	
662	// TestConfirmRecoveryReopenAndContinue 重开存档后可读到恢复的新记录，并能
663	// 继续提交、覆盖与升级。
664	func TestConfirmRecoveryReopenAndContinue(t *testing.T) {
665		a, dir := newTestArchive(t)
666		ids := saveN(t, a, "s", 2)
667		corruptChecksum(t, dir, ids[0])
668		pv, err := a.PreviewRecovery("s", []string{"v1"})
669		if err != nil {
670			t.Fatal(err)
671		}
672		info, err := a.ConfirmRecovery("s", pv.Current, pv.Source, []string{"v1"})
673		if err != nil {
674			t.Fatal(err)
675		}
676	
677		a2, err := Open(dir)
678		if err != nil {
679			t.Fatal(err)
680		}
681		rec, err := a2.Latest("s", []string{"v1"})
682		if err != nil {
683			t.Fatalf("重开后应读到新记录: %v", err)
684		}
685		if rec.ID != info.ID || rec.State.Time != 1 {
686			t.Fatalf("重开读取错误: %+v", rec)
687		}
688		// 继续提交 + 覆盖。
689		w, err := WorldFromState(rec.State)
690		if err != nil {
691			t.Fatal(err)
692		}
693		if _, err := w.Apply(Commit{Time: 3}); err != nil {
694			t.Fatal(err)
695		}
696		if _, err := a2.Replace("s", w, info.ID); err != nil {
697			t.Fatalf("恢复后覆盖失败: %v", err)
698		}
699		// 升级也照常工作。
700		latest, err := a2.Latest("s", []string{"v1"})
701		if err != nil {
702			t.Fatal(err)
703		}
704		if _, err := a2.Upgrade("s", []string{"v1"}, v2Rules(), latest.ID); err != nil {
705			t.Fatalf("恢复后升级失败: %v", err)
706		}
707	}
708	
709	// TestConfirmRecoveryExistingBranchesUnaffected 恢复前已分出的分支在恢复后
710	// 仍独立可读、可继续保存，不受本槽恢复影响。
711	func TestConfirmRecoveryExistingBranchesUnaffected(t *testing.T) {
712		a, dir := newTestArchive(t)
713		ids := saveN(t, a, "s", 3)
714		b0, err := a.Branch("s", ids[3], "b")
715		if err != nil {
716			t.Fatal(err)
717		}
718		corruptChecksum(t, dir, ids[0])
719		pv, err := a.PreviewRecovery("s", []string{"v1"})
720		if err != nil {
721			t.Fatal(err)
722		}
723		if _, err := a.ConfirmRecovery("s", pv.Current, pv.Source, []string{"v1"}); err != nil {
724			t.Fatal(err)
725		}
726	
727		brec, err := a.Latest("b", []string{"v1"})
728		if err != nil || brec.ID != b0.ID || brec.State.Time != 0 {
729			t.Fatalf("已有分支受恢复影响: %+v err=%v", brec, err)
730		}
731		wb, err := WorldFromState(brec.State)
732		if err != nil {
733			t.Fatal(err)
734		}
735		if _, err := wb.Apply(Commit{Time: 6}); err != nil {
736			t.Fatal(err)
737		}
738		if _, err := a.Replace("b", wb, b0.ID); err != nil {
739			t.Fatalf("分支继续保存失败: %v", err)
740		}
741	}
742	
743	// TestConfirmRecoveryLegacyPointer 旧格式裸指针沿用已有的历史归属限制：
744	// 当前完好时可预览并确认，确认后重建的旧历史与新记录一并持久化，从此获得
745	// 完整恢复能力；断裂链无法确认归属的旧记录仍被拒绝。
746	func TestConfirmRecoveryLegacyPointer(t *testing.T) {
747		a, dir := newTestArchive(t)
748		ids := saveN(t, a, "s", 2) // r2 r1 r0
749		writeLegacyPointer(t, a, "s", ids[0])
750	
751		a2, err := Open(dir)
752		if err != nil {
753			t.Fatal(err)
754		}
755		pv, err := a2.PreviewRecovery("s", []string{"v1"})
756		if err != nil {
757			t.Fatalf("裸指针下应可预览: %v", err)
758		}
759		if pv.Current != ids[0] || pv.Source != ids[0] {
760			t.Fatalf("预览错误: %+v", pv)
761		}
762		info, err := a2.ConfirmRecovery("s", pv.Current, pv.Source, []string{"v1"})
763		if err != nil {
764			t.Fatalf("裸指针下确认失败: %v", err)
765		}
766	
767		// 指针现在持有完整历史（新记录 + 重建出的旧链）。
768		p, err := a2.readSlotPointerLocked("s")
769		if err != nil {
770			t.Fatal(err)
771		}
772		want := []RecordID{info.ID, ids[0], ids[1], ids[2]}
773		if len(p.History) != len(want) {
774			t.Fatalf("历史应为 %v，得到 %v", want, p.History)
775		}
776		for i := range want {
777			if p.History[i] != want[i] {
778				t.Fatalf("历史次序错误: %v", p.History)
779			}
780		}
781	
782		// 新记录、旧最新与中间记录都失效时，仍能恢复到最早的首存记录——旧
783		// 历史已随确认获得完整索引，不再受单条父链断裂限制。
784		corruptChecksum(t, dir, info.ID)
785		deleteRecord(t, dir, ids[0])
786		truncateRecord(t, dir, ids[1])
787		rec, err := a2.RecoverLatest("s", []string{"v1"})
788		if err != nil {
789			t.Fatalf("应恢复到首存记录: %v", err)
790		}
791		if rec.ID != ids[2] {
792			t.Fatalf("应恢复 %s，得到 %s", ids[2], rec.ID)
793		}
794	
795		// 断裂旧链：删除中间记录并降级成裸指针，无法经断裂处确认归属的旧
796		// 记录不能作为来源（按不存在拒绝），预览也不可恢复。
797		b, _ := newTestArchive(t)
798		bids := saveN(t, b, "x", 2)
799		deleteRecord(t, b.dir, bids[1])
800		writeLegacyPointer(t, b, "x", bids[0])
801		if _, err := b.PreviewRecovery("x", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
802			t.Fatalf("断裂裸指针应不可恢复，得到 %T: %v", err, err)
803		}
804		if _, err := b.ConfirmRecovery("x", bids[0], bids[2], []string{"v1"}); !errors.As(err, new(*NotFoundError)) {
805			t.Fatalf("无法确认归属的旧记录应 NotFound，得到 %T: %v", err, err)
806		}
807	}
808	
809	// TestConfirmRecoveryInterruptedWrite 写入中断后重开：槽保持确认前指向与
810	// 历史，写完但未生效的新记录不能进入恢复候选、也不能作为来源；之后一次
811	// 真正的确认照常成功。
812	func TestConfirmRecoveryInterruptedWrite(t *testing.T) {
813		a, dir := newTestArchive(t)
814		ids := saveN(t, a, "s", 1)
815		w := baseWorld(t)
816		if _, err := w.Apply(Commit{Time: 2}); err != nil {
817			t.Fatal(err)
818		}
819		// 模拟确认在“记录已写完、指针尚未改名”时崩溃。
820		orphan := writeRawRecord(t, a, ids[1] /*来源取首存*/, false, w.Snapshot())
821		junk := filepath.Join(dir, recordsName, ".tmp-unfinished")
822		if err := os.WriteFile(junk, []byte("{x"), 0o600); err != nil {
823			t.Fatal(err)
824		}
825	
826		a2, err := Open(dir)
827		if err != nil {
828			t.Fatal(err)
829		}
830		// 指针仍指向确认前的 r1，预览选 r1，孤儿记录既不是来源也不在历史中。
831		pv, err := a2.PreviewRecovery("s", []string{"v1"})
832		if err != nil {
833			t.Fatal(err)
834		}
835		if pv.Current != ids[0] || pv.Source != ids[0] {
836			t.Fatalf("中断后预览应停在确认前状态: %+v", pv)
837		}
838		if _, err := a2.ConfirmRecovery("s", ids[0], orphan, []string{"v1"}); !errors.As(err, new(*NotFoundError)) {
839			t.Fatalf("未生效的新记录不能作为来源，得到 %T: %v", err, err)
840		}
841		// 一次真正的确认成功，历史只含新记录与原有两条，孤儿不在其中。
842		info, err := a2.ConfirmRecovery("s", ids[0], ids[1], []string{"v1"})
843		if err != nil {
844			t.Fatalf("正式确认应成功: %v", err)
845		}
846		hist, err := a2.History("s")
847		if err != nil {
848			t.Fatal(err)
849		}
850		if len(hist) != 3 {
851			t.Fatalf("历史不应包含孤儿记录: %+v", hist)
852		}
853		for _, h := range hist {
854			if h.ID == orphan {
855				t.Fatal("未生效的孤儿记录进入了历史")
856			}
857		}
858		if hist[0].ID != info.ID {
859			t.Fatalf("新记录应排在最前: %+v", hist)
860		}
861	}
862	
863	// fixPointer 在测试中把槽指针重写为仅指向 id 的完好指针（用于从“指针损坏”
864	// 场景恢复测试前提）。
865	func fixPointer(t *testing.T, a *Archive, slot string, id RecordID) {
866		t.Helper()
867		lock, err := acquireLock(a.dir)
868		if err != nil {
869			t.Fatal(err)
870		}
871		defer lock.release()
872		if err := a.persistSlotPointerLocked(slot, slotPointer{
873			Latest:  id,
874			History: []RecordID{id},
875		}); err != nil {
876			t.Fatal(err)
877		}
878	}
