19	// validateRules 校验规则本身：非空版本、地点不重复且非空标识、
20	// 连通关系只引用已有地点、物品不重复、携带上限非负。
21	func validateRules(r Rules) error {
22		if r.Version == "" {
23			return ruleErrorf("规则版本不能为空")
24		}
25		locs := make(map[string]struct{}, len(r.Locations))
26		for _, l := range r.Locations {
27			if l == "" {
28				return ruleErrorf("地点标识不能为空")
29			}
30			if _, ok := locs[l]; ok {
31				return ruleErrorf("地点标识重复: %q", l)
32			}
33			locs[l] = struct{}{}
34		}
35		for i, e := range r.Edges {
36			if _, ok := locs[e.From]; !ok {
37				return ruleErrorf("连通关系 %d 引用了不存在的地点: %q", i, e.From)
38			}
39			if _, ok := locs[e.To]; !ok {
40				return ruleErrorf("连通关系 %d 引用了不存在的地点: %q", i, e.To)
41			}
42		}
43		kinds := make(map[string]struct{}, len(r.ItemKinds))
44		for _, k := range r.ItemKinds {
45			if k == "" {
46				return ruleErrorf("物品种类标识不能为空")
47			}
48			if _, ok := kinds[k]; ok {
49				return ruleErrorf("物品种类重复: %q", k)
50			}
51			kinds[k] = struct{}{}
52		}
53		for who, limit := range r.CarryLimits {
54			if limit < 0 {
55				return ruleErrorf("角色 %q 的携带上限不能为负: %d", who, limit)
56			}
57		}
58		return nil
59	}
60	
61	func (r Rules) adjacent(from, to string) bool {
62		for _, e := range r.Edges {
63			if (e.From == from && e.To == to) || (e.From == to && e.To == from) {
64				return true
65			}
66		}
67		return false
68	}
69	
70	// validateCharacters 校验角色集合：标识不重复、位于已有地点；
71	// 物品种类合法、数量非负、不重复，总量不超过携带上限。
72	func validateCharacters(chars []Character, r Rules) error {
73		locSet := make(map[string]struct{}, len(r.Locations))
74		for _, l := range r.Locations {
75			locSet[l] = struct{}{}
76		}
77		kindSet := make(map[string]struct{}, len(r.ItemKinds))
78		for _, k := range r.ItemKinds {
79			kindSet[k] = struct{}{}
80		}
81		ids := make(map[string]struct{}, len(chars))
82		for _, c := range chars {
83			if c.ID == "" {
84				return ruleErrorf("角色标识不能为空")
85			}
86			if _, ok := ids[c.ID]; ok {
87				return ruleErrorf("角色标识重复: %q", c.ID)
88			}
89			ids[c.ID] = struct{}{}
90			if _, ok := locSet[c.Location]; !ok {
91				return ruleErrorf("角色 %q 位于不存在的地点: %q", c.ID, c.Location)
92			}
93			seen := make(map[string]struct{}, len(c.Items))
94			for _, it := range c.Items {
95				if _, ok := kindSet[it.Item]; !ok {
96					return ruleErrorf("角色 %q 持有规则不允许的物品: %q", c.ID, it.Item)
97				}
98				if _, dup := seen[it.Item]; dup {
99					return ruleErrorf("角色 %q 的物品 %q 重复列出", c.ID, it.Item)
100				}
101				seen[it.Item] = struct{}{}
102				if it.Count < 0 {
103					return ruleErrorf("角色 %q 的物品 %q 数量不能为负: %d", c.ID, it.Item, it.Count)
104				}
105			}
106			// 携带上限按真实总量判断：精确求和，不因加法回绕而放过超限。
107			// 未设上限的角色不检查总量，其总量允许超过 int 最大值。
108			if limit, hasLimit := r.CarryLimits[c.ID]; hasLimit {
109				total := new(big.Int)
110				for _, it := range c.Items {
111					total.Add(total, bigInt(it.Count))
112				}
113				if total.Cmp(bigInt(limit)) > 0 {
114					return ruleErrorf("角色 %q 携带总量 %s 超过上限 %d", c.ID, total.String(), limit)
115				}
116			}
117		}
118		return nil
119	}
120	
121	// validateInitialData 校验建立世界的初始数据。
122	func validateInitialData(d InitialData) error {
123		if err := validateRules(d.Rules); err != nil {
124			return err
125		}
126		if err := validateCharacters(d.Characters, d.Rules); err != nil {
127			return err
128		}
129		return nil
130	}
